WITH filtered AS (SELECT id, order_id, method, status, CASE WHEN method = 'paypal' THEN 1 ELSE 0 END AS is_paypal, COALESCE(method, 'N/A') AS method_clean FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-07-24 06:00:00') AND method = 'promptpay') SELECT * FROM (SELECT order_id, status, method, is_paypal FROM filtered) src PIVOT (SUM(is_paypal) AS amount FOR method IN ('paypal', 'promptpay'));
